const examTypes = $('配置: 考试类型').first().json.exam_types.split(',');
const limit = $('配置: 考试类型').first().json.batch_limit;

// 为每种考试类型生成一个任务
const items = examTypes.slice(0, limit).map((type, index) => ({
  json: {
    exam_type: type.trim(),
    index: index
  }
}));

return items;

// 🧹 暴力清洗解析
const raw = items[0].json.choices[0].message.content;

// 去除非法字符
const clean = raw.replace(/```json/g, '').replace(/```/g, '').trim();

// 解析成对象
let data = {};
try {
  data = JSON.parse(clean);
} catch (e) {
  console.error('JSON解析错误:', e);
  data = {
    sections: []
  };
}

// 获取考试类型
const examType = $('逐类型处理').item.json.exam_type;

// 确保sections存在
if (!data.sections || !Array.isArray(data.sections)) {
  data.sections = [];
}

// 输出纯净数据
return [{
  json: {
    exam_type: examType,
    sections: data.sections
  }
}];
